css:
/* ── Wrapper ── */
.billing-run-print {
    font-family: "Helvetica Neue", Helvetica, Arial, sans-serif;
    font-size: 13px;
    color: #333333;
    padding: 10px;
}

/* ── Header ── */
.print-header {
    border-bottom: 2px solid #1F497D;
    padding-bottom: 15px;
    margin-bottom: 25px;
}
.header-title {
    color: #1F497D;
    font-size: 22px;
    font-weight: bold;
    text-align: center;
    margin-top: 0;
    margin-bottom: 14px;
    letter-spacing: 0.3px;
}
.header-row {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    margin-bottom: 4px;
}
.header-row p {
    margin: 0;
    font-size: 13px;
    flex: 1;
}
.header-row p:last-child {
    text-align: right;
}

/* ── Sections ── */
.print-section {
    margin-bottom: 35px;
}
.print-section h3 {
    color: #1F497D;
    font-size: 15px;
    font-weight: bold;
    border-bottom: 1px solid #dddddd;
    padding-bottom: 5px;
    margin-top: 0;
    margin-bottom: 15px;
}

/* ── Scrollable Table Wrapper ── */
.table-scroll-wrapper {
    width: 100%;
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
}

/* ── Tables ── */
.table {
    width: 100%;
    margin-bottom: 20px;
    border-collapse: collapse;
}
.table-bordered th,
.table-bordered td {
    border: 1px solid #dddddd !important;
    padding: 7px 8px !important;
    vertical-align: middle !important;
}
.table-condensed th,
.table-condensed td {
    padding: 5px 7px !important;
}
.table-striped tbody tr:nth-child(odd) {
    background-color: #f9f9f9;
}
.table thead th {
    background-color: #f0f4f9;
    font-weight: bold;
    color: #1F497D;
    font-size: 12px;
    white-space: nowrap;
}

/* ── Total Row ── */
.total-row td {
    background-color: #f5f8fc;
    border-top: 1.5px solid #1F497D !important;
    border-bottom: 3px double #1F497D !important;
    font-size: 13px;
}

/* ── Utility Classes ── */
.text-right  { text-align: right  !important; }
.text-left   { text-align: left   !important; }
.text-center { text-align: center !important; }
.font-bold   { font-weight: bold  !important; }

/* ── Print ── */
@media print {
    .billing-run-print { padding: 0; }
    .page-break-before { page-break-before: avoid; }
    .table-scroll-wrapper { overflow-x: visible; }
    .header-row { display: flex; justify-content: space-between; }
    .table-bordered th,
    .table-bordered td { font-size: 9px !important; padding: 3px 4px !important; }
    .table thead th { font-size: 9px !important; white-space: nowrap; }
    .print-header h2 { font-size: 18px; }
    .print-section h3 { font-size: 13px; }
    .table { table-layout: auto; word-wrap: break-word; font-size: 9px !important; }
}

@page {
    size: A4 landscape;
    margin: 12mm 10mm;
}
